// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    address owner = address(0x123);

    function setUp() public {
        vm.prank(owner);
        c = new SimpleWallet();
    }

    function testFuzz_property(address _target, uint256 _value) public {
        vm.assume(_target != address(c));
        vm.assume(_value <= address(this).balance);

        vm.deal(address(c), _value);
        vm.prank(owner);
        c.sendMoney(_target, _value);

        vm.prank(owner);
        bool ok = true;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}
